        System.out.println("Making a Hippo");
    }
}
public class TestHippo {
    public static void main(String[] args) {
        System.out.println("Starting...");
        Hippo h = new Hippo();
    }
}
// 输出（选项 A）：
// Starting...
// Making an Animal     ← 父类先完成
// Making a Hippo       ← 子类后完成
// 注意：Hippo() 最先被调用，却是最后一个完成

public class Duck extends Animal {
    int size;
    public Duck(int newSize) {
        // Animal();        // 错误！这不是合法语法，编译器当成找 Animal() 方法
        super();            // 唯一正确方式：调父类构造器，且必须是第一句
        size = newSize;
    }
}

// super() 必须排第一——正例与反例
class Boop {
    int size;
    public Boop() { super(); }                 // OK：显式 super() 在第一句
    public Boop(int i) { super(); size = i; }  // OK
    public Boop(String s) { size = 3; }        // OK：编译器补无参 super() 到开头
    // public Boop(int i) { size = i; super(); } // 编译失败：super() 不在第一句
}

public abstract class Animal {
    private String name;                     // private：子类不可直接访问
    public String getName() { return name; } // 但子类继承了读取它的方法
    public Animal(String theName) {          // 只有带参构造器，没有无参版本
        name = theName;
    }
}
public class Hippo extends Animal {
    public Hippo(String name) {
        super(name);                         // 必须显式传值，否则编译器补 super() 会失败
    }
}
public class MakeHippo {
    public static void main(String[] args) {
        Hippo h = new Hippo("Buffy");
        System.out.println(h.getName());     // 输出 Buffy
    }
}

import java.awt.Color;
class Car {
    Car(String name) { }
    Car(int size) { }
}
class Mini extends Car {
    private Color color;
    public Mini() {
        this(Color.RED);            // 第一句：转发给真正的构造器
    }
    public Mini(Color c) {
        super("Mini");              // 整条链里唯一一次 super()
        color = c;
    }
    public Mini(int size) {
        this(Color.RED);
        // super(size);             // 编译失败：super() 与 this() 不能共存
    }
}
// new Mini() 的链：Mini() → this(Color.RED) → Mini(Color) → super("Mini") → Car 构造 → 回到 Mini(Color) 设 color → 完成
